// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL     string
	Middlewares []MiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Get(options.BaseURL+"/api/v1/admin/jobs", wrapper.ListAdminJobs)

	router.Get(options.BaseURL+"/api/v1/admin/jobs/:jobId", wrapper.GetAdminJob)

	router.Post(options.BaseURL+"/api/v1/admin/jobs/:jobId/cancel", wrapper.CancelAdminJob)

	router.Post(options.BaseURL+"/api/v1/admin/jobs/:jobId/retry", wrapper.RetryAdminJob)

	router.Get(options.BaseURL+"/api/v1/audit", wrapper.ListAudit)

	router.Get(options.BaseURL+"/api/v1/audit/export", wrapper.ExportAudit)

	router.Get(options.BaseURL+"/api/v1/audit/:auditId", wrapper.GetAudit)

	router.Post(options.BaseURL+"/api/v1/auth/login", wrapper.Login)

	router.Post(options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)

	router.Get(options.BaseURL+"/api/v1/auth/me", wrapper.GetCurrentUser)

	router.Patch(options.BaseURL+"/api/v1/auth/me", wrapper.UpdateCurrentUser)

	router.Post(options.BaseURL+"/api/v1/auth/mfa/challenge", wrapper.ChallengeMFA)

	router.Get(options.BaseURL+"/api/v1/auth/oauth/:provider/callback", wrapper.CallbackOAuth)

	router.Get(options.BaseURL+"/api/v1/auth/oauth/:provider/start", wrapper.StartOAuth)

	router.Get(options.BaseURL+"/api/v1/auth/oidc/:provider/callback", wrapper.CallbackOIDC)

	router.Get(options.BaseURL+"/api/v1/auth/oidc/:provider/start", wrapper.StartOIDC)

	router.Post(options.BaseURL+"/api/v1/auth/password-reset/confirm", wrapper.ConfirmPasswordReset)

	router.Post(options.BaseURL+"/api/v1/auth/password-reset/request", wrapper.RequestPasswordReset)

	router.Get(options.BaseURL+"/api/v1/auth/personal-access-tokens", wrapper.ListPersonalAccessTokens)

	router.Post(options.BaseURL+"/api/v1/auth/personal-access-tokens", wrapper.CreatePersonalAccessToken)

	router.Delete(options.BaseURL+"/api/v1/auth/personal-access-tokens/:tokenId", wrapper.DeletePersonalAccessToken)

	router.Post(options.BaseURL+"/api/v1/auth/refresh", wrapper.Refresh)

	router.Post(options.BaseURL+"/api/v1/auth/register", wrapper.Register)

	router.Post(options.BaseURL+"/api/v1/auth/resend-verification", wrapper.ResendVerification)

	router.Get(options.BaseURL+"/api/v1/auth/saml/metadata", wrapper.MetadataSAML)

	router.Post(options.BaseURL+"/api/v1/auth/saml/:provider/acs", wrapper.AssertionConsumerServiceSAML)

	router.Get(options.BaseURL+"/api/v1/auth/saml/:provider/start", wrapper.StartSAML)

	router.Post(options.BaseURL+"/api/v1/auth/verify-email", wrapper.VerifyEmail)

	router.Get(options.BaseURL+"/api/v1/me/identities", wrapper.ListMyIdentities)

	router.Delete(options.BaseURL+"/api/v1/me/identities/:identityId", wrapper.DeleteMyIdentity)

	router.Get(options.BaseURL+"/api/v1/me/mfa/recovery", wrapper.ListMyRecoveryCodes)

	router.Post(options.BaseURL+"/api/v1/me/mfa/recovery", wrapper.RegenerateMyRecoveryCodes)

	router.Post(options.BaseURL+"/api/v1/me/mfa/totp/disable", wrapper.DisableTOTP)

	router.Post(options.BaseURL+"/api/v1/me/mfa/totp/enroll", wrapper.EnrollTOTP)

	router.Post(options.BaseURL+"/api/v1/me/mfa/totp/verify", wrapper.VerifyTOTP)

	router.Delete(options.BaseURL+"/api/v1/me/mfa/webauthn/credentials/:credentialId", wrapper.DeleteWebAuthnCredential)

	router.Post(options.BaseURL+"/api/v1/me/mfa/webauthn/login/begin", wrapper.BeginWebAuthnLogin)

	router.Post(options.BaseURL+"/api/v1/me/mfa/webauthn/login/finish", wrapper.FinishWebAuthnLogin)

	router.Post(options.BaseURL+"/api/v1/me/mfa/webauthn/register/begin", wrapper.BeginWebAuthnRegistration)

	router.Post(options.BaseURL+"/api/v1/me/mfa/webauthn/register/finish", wrapper.FinishWebAuthnRegistration)

	router.Get(options.BaseURL+"/api/v1/ping", wrapper.Ping)

	router.Get(options.BaseURL+"/health", wrapper.GetHealth)

}

